//! The types for speaking to zconnor: the Mailbox gRPC service face
//! and the mail vocabulary it transits — one crate, named after the
//! owner and the cargo word. Link contracts
//! live in their own crates; this one is stdio-free by construction.
//!
//! Generated files are included in modules mirroring their proto
//! packages: the cross-package references resolve against that
//! hierarchy.

// Generated by [`prost-build`]
pub mod zconn {
    pub mod zconned {
        pub mod mail {
            // Same-package protos (mail.proto + mail_spk_opk.proto)
            // merge into ONE generated file.
            include!(concat!(env!("OUT_DIR"), "/zconn.zconned.mail.rs"));
        }
        pub mod relay {
            include!(concat!(env!("OUT_DIR"), "/zconn.zconned.relay.rs"));
        }
    }
}

pub use zconn::zconned::mail;
pub use zconn::zconned::relay;

// The link's own version count: starts at 1, never compared
// cross-space.
pub const PROTOCOL_VERSION: u32 = 1;

/// The in-band error codes (transport failures ride gRPC Status).
pub mod error_code {
    /// A bundle request against an unknown or unregistered mailbox.
    pub const MAILBOX_UNKNOWN: &str = "mailbox_unknown";
    /// The sender's cached SPK no longer matches the receiver's
    /// standing one — re-establish.
    pub const STALE_PREKEY: &str = "stale_prekey";
}

#[cfg(test)]
mod tests {
    use super::*;
    use prost::Message as _;

    fn sample_mail() -> mail::Mail {
        mail::Mail {
            to_mailbox: vec![0xaa; 32],
            from_mailbox: vec![0xbb; 32],
            key_version: 1,
            dr_header: Some(mail::DrHeader {
                ratchet_pub: vec![0xcc; 32],
                chain_seq: 7,
            }),
            sig: vec![0xdd; 64],
            ciphertext: vec![0xee; 48],
            establishment: None,
        }
    }

    #[test]
    fn mail_roundtrips_through_transport_bytes() {
        let m = sample_mail();
        let bytes = m.encode_to_vec();
        assert_eq!(mail::Mail::decode(bytes.as_slice()).unwrap(), m);
    }

    #[test]
    fn unsealed_slots_are_empty_by_default() {
        // A freshly built Mail is the SEALED form: only the header
        // fields are set; there is no plaintext slot at all.
        let m = mail::Mail::default();
        assert!(m.ciphertext.is_empty());
        assert!(m.dr_header.is_none());
    }

    #[test]
    fn prekey_shapes_roundtrip() {
        let spk = mail::Spk {
            key: vec![0x01; 32],
            sig: vec![0x02; 64],
            ver: 1,
        };
        let opk = mail::Opk {
            id: 42,
            key: vec![0x03; 32],
        };
        assert_eq!(
            mail::Spk::decode(spk.encode_to_vec().as_slice()).unwrap(),
            spk
        );
        assert_eq!(
            mail::Opk::decode(opk.encode_to_vec().as_slice()).unwrap(),
            opk
        );
    }

    #[test]
    fn plane_frame_downstream_oneof_roundtrips() {
        let frame = relay::PlaneFrame {
            frame: Some(relay::plane_frame::Frame::Mail(sample_mail())),
        };
        let bytes = frame.encode_to_vec();
        match relay::PlaneFrame::decode(bytes.as_slice()).unwrap().frame {
            Some(relay::plane_frame::Frame::Mail(m)) => assert_eq!(m, sample_mail()),
            other => panic!("expected the mail branch, got {other:?}"),
        }
    }

    #[test]
    fn bundle_carries_the_pool_remaining_report() {
        let bundle = relay::Bundle {
            mailbox: vec![0xaa; 32],
            spk: Some(mail::Spk {
                key: vec![0x01; 32],
                sig: vec![0x02; 64],
                ver: 1,
            }),
            opk: Some(mail::Opk {
                id: 1,
                key: vec![0x03; 32],
            }),
            pool_remaining: 3,
        };
        let bytes = bundle.encode_to_vec();
        assert_eq!(relay::Bundle::decode(bytes.as_slice()).unwrap(), bundle);
    }

    #[test]
    fn mailbox_service_is_generated() {
        // Naming the generated trait compiles = the 11-method
        // Mailbox service was generated (the trait exists only when
        // a service block was processed).
        // Definition-only witness: compiles iff the generated
        // Mailbox trait path exists (never instantiated).
        #[allow(dead_code)]
        fn witness<T: relay::mailbox_server::Mailbox>(_: &T) {}
    }

    #[test]
    fn peer_record_roundtrips() {
        let peer = mail::Peer {
            address: Some(mail::PeerAddress {
                algo: "sha3-256".to_owned(),
                digest: vec![0xab; 32],
            }),
            mailbox: Some(mail::MailboxPublicSet::default()),
            endpoints: vec![mail::Endpoint {
                ip: "192.168.1.10".to_owned(),
                port: 7100,
            }],
        };
        let bytes = peer.encode_to_vec();
        assert_eq!(mail::Peer::decode(bytes.as_slice()).unwrap(), peer);
    }
}
